          'Découvrez une nouvelle dimension de compétition entre collègues !\n\nVous souhaitez savoir comment vous vous situez par rapport à vos collègues passionnés de sport, de paris  ou e sport ? Indiquez simplement le nom de votre entreprise dans votre profil !\n\nCette fonctionnalité vous offre la possibilité unique de vous mesurer à vos collègues au sein de votre société. Nous tenons à vous garantir que les informations relatives à votre entreprise sont entièrement confidentielles et ne seront en aucun cas divulguées publiquement sur votre profil.\n\nN\'attendez plus, mettez à jour votre profil et lancez la compétition amicale au sein de votre entreprise !',
      'de': '',
      'en': '',
      'es': '',
      'it': '',
      'pt': '',
    },
    'zphl8jov': {
      'fr':
          'Discover a new dimension of competition between colleagues!\n\nWant to know how you compare to your fellow sports, betting, or esports enthusiasts? Simply enter your company name in your profile!\n\nThis feature offers you the unique opportunity to compete with your colleagues within your company. We assure you that your company information is completely confidential and will never be publicly disclosed on your profile.\n\nDon\'t wait any longer, update your profile, and start some friendly competition within your company!',
      'de': '',
      'en': '',
      'es': '',
      'it': '',
      'pt': '',
    },
    'zktqfxwn': {
      'fr':
          'Entdecken Sie eine neue Dimension des Wettbewerbs unter Kollegen!\n\nMöchten Sie wissen, wie Sie im Vergleich zu Ihren Sport-, Wett- oder E-Sport-Begeistertenkollegen abschneiden? Tragen Sie Ihren Firmennamen einfach in Ihr Profil ein!\n\nDiese Funktion bietet Ihnen die einzigartige Möglichkeit, sich mit Ihren Kollegen innerhalb Ihres Unternehmens zu messen. Wir möchten Ihnen versichern, dass Ihre Unternehmensinformationen absolut vertraulich behandelt werden und unter keinen Umständen öffentlich in Ihrem Profil preisgegeben werden.\n\nWarten Sie nicht länger, aktualisieren Sie Ihr Profil und starten Sie den freundschaftlichen Wettbewerb innerhalb Ihres Unternehmens!',
      'de': '',
      'en': '',
      'es': '',
      'it': '',
      'pt': '',
    },
    'ncby24l2': {
      'fr':
          '¡Descubre una nueva dimensión de competición entre colegas!\n\n¿Quieres saber cómo te comparas con tus compañeros entusiastas de los deportes, las apuestas o los deportes electrónicos? ¡Simplemente incluya el nombre de su empresa en su perfil!\n\nEsta característica le brinda la oportunidad única de competir con sus colegas dentro de su empresa. Queremos asegurarle que la información de su empresa es completamente confidencial y no se divulgará públicamente en su perfil bajo ninguna circunstancia.\n\n¡No esperes más, actualiza tu perfil y comienza la competencia amistosa dentro de tu empresa!',
      'de': '',
      'en': '',
      'es': '',
      'it': '',
      'pt': '',
    },
    'wmuefh7h': {
      'fr':
          'Scopri una nuova dimensione di competizione tra colleghi!\n\nVuoi sapere come ti confronti con i tuoi colleghi appassionati di sport, scommesse o e-sport? Basta includere il nome della tua azienda nel tuo profilo!\n\nQuesta funzionalità ti offre l\'opportunità unica di competere con i tuoi colleghi all\'interno della tua azienda. Vogliamo assicurarti che le informazioni sulla tua azienda sono assolutamente riservate e non verranno divulgate pubblicamente sul tuo profilo in nessuna circostanza.\n\nNon aspettare oltre, aggiorna il tuo profilo e inizia la competizione amichevole all\'interno della tua azienda!',
      'de': '',
      'en': '',
      'es': '',
      'it': '',
      'pt': '',
    },
    'cdqyse3h': {
      'fr':
          'Descubra uma nova dimensão de competição entre colegas!\n\nQuer saber como se compara com outros entusiastas de desporto, apostas ou e-sports? Basta incluir o nome da sua empresa no seu perfil!\n\nEsta funcionalidade dá-lhe uma oportunidade única de competir com os seus colegas dentro da sua empresa. Queremos garantir que as informações da sua empresa são completamente confidenciais e não serão divulgadas publicamente no seu perfil em nenhuma circunstância.\n\nNão espere mais, atualize o seu perfil e inicie a competição amigável dentro da sua empresa!',
