          'The S Team Sport requiert l\'accès à votre appareil photo pour vous permettre de personnaliser votre photo de profil, rendant votre expérience plus personnelle et reconnaissable au sein de la communauté. De plus, l\'accès à l\'appareil photo est nécessaire pour utiliser la fonctionnalité de prise de photos lors de la rédaction de commentaires, vous permettant de partager des moments, des preuves ou des illustrations pertinentes avec les autres utilisateurs. Aucune autre utilisation de votre appareil photo n\'est prévue, et les photos prises sont uniquement stockées localement sur votre appareil et/ou sur nos serveurs Firebase dans le cadre de votre contenu utilisateur.',
      'de':
          'S Team Sport benötigt Zugriff auf Ihre Kamera, damit Sie Ihr Profilbild anpassen und Ihr Erlebnis persönlicher und innerhalb der Community erkennbarer gestalten können. Darüber hinaus ist Kamerazugriff erforderlich, um beim Kommentieren die Fotofunktion zu verwenden, mit der Sie relevante Momente, Beweise oder Illustrationen mit anderen Benutzern teilen können. Eine andere Verwendung Ihrer Kamera ist nicht vorgesehen und aufgenommene Fotos werden nur lokal auf Ihrem Gerät und/oder auf unseren Firebase-Servern als Teil Ihres Benutzerinhalts gespeichert.',
      'en':
          'The S Team Sport requires access to your camera to allow you to customize your profile picture, making your experience more personal and recognizable within the community. Additionally, camera access is required to use the photo-taking feature when writing comments, allowing you to share relevant moments, evidence, or illustrations with other users. No other use of your camera is intended, and the photos taken are only stored locally on your device and/or on our Firebase servers as part of your user content.',
      'es':
          'El equipo S Team Sport requiere acceso a tu cámara para permitirte personalizar tu foto de perfil, haciendo tu experiencia más personal y reconocible dentro de la comunidad. Además, se requiere acceso a la cámara para usar la función de tomar fotografías al comentar, lo que le permite compartir momentos, evidencia o ilustraciones relevantes con otros usuarios. No se pretende ningún otro uso de su cámara y las fotografías tomadas solo se almacenan localmente en su dispositivo y/o en nuestros servidores Firebase como parte de su Contenido de usuario.',
      'it':
          'S Team Sport richiede l\'accesso alla tua fotocamera per consentirti di personalizzare la tua immagine del profilo, rendendo la tua esperienza più personale e riconoscibile all\'interno della community. Inoltre, per utilizzare la funzione di scatto delle foto durante i commenti, è necessario l\'accesso alla fotocamera, che consente di condividere momenti, prove o illustrazioni rilevanti con altri utenti. Non è previsto alcun altro utilizzo della tua fotocamera e le foto scattate vengono archiviate solo localmente sul tuo dispositivo e/o sui nostri server Firebase come parte dei tuoi Contenuti utente.',
      'pt':
          'O S Team Sport requer acesso à sua câmera para permitir que você personalize sua foto de perfil, tornando sua experiência mais pessoal e reconhecível dentro da comunidade. Além disso, é necessário acesso à câmera para usar o recurso de tirar fotos ao comentar, permitindo que você compartilhe momentos relevantes, evidências ou ilustrações com outros usuários. Nenhum outro uso da sua câmera é pretendido, e as fotos tiradas são armazenadas apenas localmente no seu dispositivo e/ou em nossos servidores Firebase como parte do seu Conteúdo do Usuário.',
    },
    'y6yovacn': {
      'fr':
          'The S Team Sport souhaite accéder à votre photothèque afin de vous offrir la possibilité de sélectionner une photo existante comme photo de profil, vous offrant ainsi plus de flexibilité dans la personnalisation de votre compte. Cet accès est également requis si vous souhaitez joindre des photos depuis votre galerie lorsque vous rédigez des commentaires, vous permettant de partager des images que vous avez déjà prises. Nous n\'accéderons à aucune autre photo de votre photothèque, et les images sélectionnées seront uniquement utilisées pour votre photo de profil et vos commentaires au sein de l\'application, stockées localement sur votre appareil et/ou sur nos serveurs Firebase dans le cadre de votre contenu utilisateur.',
      'de':
          'Das S Team Sport möchte auf Ihre Fotobibliothek zugreifen, um Ihnen die Möglichkeit zu bieten, ein vorhandenes Foto als Profilbild auszuwählen und Ihnen so mehr Flexibilität bei der Anpassung Ihres Kontos zu geben. Dieser Zugriff ist auch erforderlich, wenn Sie beim Schreiben von Kommentaren Fotos aus Ihrer Galerie anhängen möchten, um bereits aufgenommene Bilder zu teilen. Wir greifen nicht auf andere Fotos in Ihrer Fotobibliothek zu und die ausgewählten Bilder werden nur für Ihr Profilbild und In-App-Kommentare verwendet und lokal auf Ihrem Gerät und/oder auf unseren Firebase-Servern als Teil Ihres Benutzerinhalts gespeichert.',
      'en':
          'The S Team Sport would like to access your photo library to provide you with the ability to select an existing photo as your profile picture, giving you more flexibility in customizing your account. This access is also required if you wish to attach photos from your gallery when writing comments, allowing you to share images you have already taken. We will not access any other photos in your photo library, and the selected images will only be used for your profile picture and comments within the app, stored locally on your device and/or on our Firebase servers as part of your user content.',
      'es':
          'Al equipo S Team Sport le gustaría acceder a su biblioteca de fotos para ofrecerle la posibilidad de seleccionar una foto existente como su foto de perfil, brindándole más flexibilidad para personalizar su cuenta. Este acceso también es necesario si deseas adjuntar fotos de tu galería al escribir comentarios, lo que te permitirá compartir imágenes que ya hayas tomado. No accederemos a ninguna otra foto de su biblioteca de fotos, y las imágenes seleccionadas solo se usarán para su foto de perfil y comentarios en la aplicación, almacenados localmente en su dispositivo y/o en nuestros servidores Firebase como parte de su Contenido de usuario.',
      'it':
          'Il team S Sport vorrebbe accedere alla tua libreria fotografica per offrirti la possibilità di selezionare una foto esistente come immagine del profilo, offrendoti maggiore flessibilità nella personalizzazione del tuo account. Questo accesso è necessario anche se vuoi allegare foto dalla tua galleria quando scrivi commenti, consentendoti di condividere le immagini che hai già scattato. Non accederemo ad altre foto presenti nella tua libreria fotografica e le immagini selezionate verranno utilizzate solo per la tua immagine del profilo e per i commenti nell\'app, archiviate localmente sul tuo dispositivo e/o sui nostri server Firebase come parte dei tuoi Contenuti utente.',
      'pt':
          'A S Team Sport gostaria de acessar sua biblioteca de fotos para lhe oferecer a possibilidade de selecionar uma foto existente como sua foto de perfil, dando a você mais flexibilidade na personalização de sua conta. Esse acesso também é necessário se você quiser anexar fotos da sua galeria ao escrever comentários, permitindo que você compartilhe imagens que já tirou. Não acessaremos nenhuma outra foto na sua biblioteca de fotos, e as imagens selecionadas serão usadas apenas para sua foto de perfil e comentários no aplicativo, armazenadas localmente no seu dispositivo e/ou em nossos servidores Firebase como parte do seu Conteúdo do Usuário.',
    },
    '3md5izby': {
      'fr':
          'The S Team Sport requiert l\'accès à votre microphone afin de vous offrir la possibilité d\'enregistrer des commentaires vocaux en réponse à des publications ou à d\'autres commentaires. Cette fonctionnalité vous permet de partager vos pensées et vos réactions de manière plus rapide et expressive, enrichissant ainsi les discussions au sein de la communauté. L\'accès au microphone est uniquement utilisé lorsque vous initiez volontairement l\'enregistrement d\'un commentaire vocal. Aucun enregistrement audio n\'est effectué à votre insu, et les enregistrements sont uniquement stockés localement sur votre appareil et/ou sur nos serveurs Firebase dans le cadre de votre contenu utilisateur.',
      'de':
          'S Team Sport benötigt Zugriff auf Ihr Mikrofon, um Ihnen die Möglichkeit zu geben, Sprachkommentare als Antwort auf Beiträge oder andere Kommentare aufzuzeichnen. Mit dieser Funktion können Sie Ihre Gedanken und Reaktionen schneller und ausdrucksstärker mitteilen und so die Diskussionen innerhalb der Community bereichern. Der Mikrofonzugriff wird nur verwendet, wenn Sie freiwillig die Aufzeichnung eines Sprachkommentars starten. Es werden keine Audioaufnahmen ohne Ihr Wissen gemacht und die Aufnahmen werden nur lokal auf Ihrem Gerät und/oder auf unseren Firebase-Servern als Teil Ihres Benutzerinhalts gespeichert.',
      'en':
          'The S Team Sport requires access to your microphone to provide you with the ability to record voice comments in response to posts or other comments. This feature allows you to share your thoughts and reactions more quickly and expressively, enriching discussions within the community. Microphone access is only used when you voluntarily initiate the recording of a voice comment. No audio recording is made without your knowledge, and recordings are only stored locally on your device and/or on our Firebase servers as part of your User Content.',
      'es':
          'El equipo S Team Sport requiere acceso a su micrófono para brindarle la posibilidad de grabar comentarios de voz en respuesta a publicaciones u otros comentarios. Esta función le permite compartir sus pensamientos y reacciones de forma más rápida y expresiva, enriqueciendo las discusiones dentro de la comunidad. El acceso al micrófono solo se utiliza cuando usted inicia voluntariamente la grabación de un comentario de voz. No se realiza ninguna grabación de audio sin su conocimiento y las grabaciones solo se almacenan localmente en su dispositivo y/o en nuestros servidores Firebase como parte de su Contenido de usuario.',
      'it':
          'S Team Sport necessita dell\'accesso al tuo microfono per consentirti di registrare commenti vocali in risposta ai post o ad altri commenti. Questa funzionalità ti consente di condividere pensieri e reazioni in modo più rapido ed espressivo, arricchendo le discussioni all\'interno della community. L\'accesso al microfono viene utilizzato solo quando si avvia volontariamente la registrazione di un commento vocale. Nessuna registrazione audio viene effettuata senza la tua conoscenza e le registrazioni vengono archiviate solo localmente sul tuo dispositivo e/o sui nostri server Firebase come parte dei tuoi Contenuti utente.',
      'pt':
          'O S Team Sport requer acesso ao seu microfone para que você possa gravar comentários de voz em resposta a postagens ou outros comentários. Esse recurso permite que você compartilhe seus pensamentos e reações de forma mais rápida e expressiva, enriquecendo as discussões dentro da comunidade. O acesso ao microfone só é usado quando você inicia voluntariamente a gravação de um comentário de voz. Nenhuma gravação de áudio é feita sem o seu conhecimento, e as gravações são armazenadas apenas localmente no seu dispositivo e/ou em nossos servidores Firebase como parte do seu Conteúdo do Usuário.',
    },
    '0e6emcr8': {
      'fr':
          'The S Team Sport requiert l\'accès à votre microphone afin de vous offrir la possibilité d\'enregistrer des commentaires vocaux en réponse à des publications ou à d\'autres commentaires. Cette fonctionnalité vous permet de partager vos pensées et vos réactions de manière plus rapide et expressive, enrichissant ainsi les discussions au sein de la communauté. L\'accès au microphone est uniquement utilisé lorsque vous initiez volontairement l\'enregistrement d\'un commentaire vocal. Aucun enregistrement audio n\'est effectué à votre insu, et les enregistrements sont uniquement stockés localement sur votre appareil et/ou sur nos serveurs Firebase dans le cadre de votre contenu utilisateur.',
      'de':
          'S Team Sport benötigt Zugriff auf Ihr Mikrofon, um Ihnen die Möglichkeit zu geben, Sprachkommentare als Antwort auf Beiträge oder andere Kommentare aufzuzeichnen. Mit dieser Funktion können Sie Ihre Gedanken und Reaktionen schneller und ausdrucksstärker mitteilen und so die Diskussionen innerhalb der Community bereichern. Der Mikrofonzugriff wird nur verwendet, wenn Sie freiwillig die Aufzeichnung eines Sprachkommentars starten. Es werden keine Audioaufnahmen ohne Ihr Wissen gemacht und die Aufnahmen werden nur lokal auf Ihrem Gerät und/oder auf unseren Firebase-Servern als Teil Ihres Benutzerinhalts gespeichert.',
      'en':
          'The S Team Sport requires access to your microphone to provide you with the ability to record voice comments in response to posts or other comments. This feature allows you to share your thoughts and reactions more quickly and expressively, enriching discussions within the community. Microphone access is only used when you voluntarily initiate the recording of a voice comment. No audio recording is made without your knowledge, and recordings are only stored locally on your device and/or on our Firebase servers as part of your User Content.',
      'es':
          'El equipo S Team Sport requiere acceso a su micrófono para brindarle la posibilidad de grabar comentarios de voz en respuesta a publicaciones u otros comentarios. Esta función le permite compartir sus pensamientos y reacciones de forma más rápida y expresiva, enriqueciendo las discusiones dentro de la comunidad. El acceso al micrófono solo se utiliza cuando usted inicia voluntariamente la grabación de un comentario de voz. No se realiza ninguna grabación de audio sin su conocimiento y las grabaciones solo se almacenan localmente en su dispositivo y/o en nuestros servidores Firebase como parte de su Contenido de usuario.',
      'it':
          'S Team Sport necessita dell\'accesso al tuo microfono per consentirti di registrare commenti vocali in risposta ai post o ad altri commenti. Questa funzionalità ti consente di condividere pensieri e reazioni in modo più rapido ed espressivo, arricchendo le discussioni all\'interno della community. L\'accesso al microfono viene utilizzato solo quando si avvia volontariamente la registrazione di un commento vocale. Nessuna registrazione audio viene effettuata senza la tua conoscenza e le registrazioni vengono archiviate solo localmente sul tuo dispositivo e/o sui nostri server Firebase come parte dei tuoi Contenuti utente.',
      'pt':
          'O S Team Sport requer acesso ao seu microfone para que você possa gravar comentários de voz em resposta a postagens ou outros comentários. Esse recurso permite que você compartilhe seus pensamentos e reações de forma mais rápida e expressiva, enriquecendo as discussões dentro da comunidade. O acesso ao microfone só é usado quando você inicia voluntariamente a gravação de um comentário de voz. Nenhuma gravação de áudio é feita sem o seu conhecimento, e as gravações são armazenadas apenas localmente no seu dispositivo e/ou em nossos servidores Firebase como parte do seu Conteúdo do Usuário.',
    },
